// ---------------------------------------------------------------------------
// Paint pricing (based on total house sqft entered in step 2)
// ---------------------------------------------------------------------------
const PAINT_BASE_SMALL = 1300; // < 500 sqft, flat price — fallback for Condo/Other only
const PAINT_BASE = 2599; // 500 - 1200 sqft, flat price — fallback for Condo/Other only
const PAINT_RATE_ABOVE = 3; // RM per sqft, applied to full sqft when > 1200 — fallback for Condo/Other only

function calcPaint(sqft) {
  if (!sqft || sqft <= 0) return 0;
  if (sqft < 500) return PAINT_BASE_SMALL;
  if (sqft <= 1200) return PAINT_BASE;
  return sqft * PAINT_RATE_ABOVE;
}

// Flat interior/exterior painting rates by property type / Landed subtype.
// null = needs on-site measurement (Bungalow, Shoplot). Condo and "Other"
// aren't covered by this table (BGL hasn't given flat rates for those), so
// they fall back to the old sqft-tiered calcPaint() above.
const PAINT_PROPERTY_RATES = {
  single: { interior: 3500, exterior: 3000 },
  double: { interior: 6500, exterior: 3500 },
  "semi-d": { interior: 12000, exterior: 8500 },
  bungalow: { interior: null, exterior: null },
  shoplot: { interior: null, exterior: null },
};

function getPropertyPaintRate(propertyType, landedSubtype) {
  if (propertyType === "landed" && landedSubtype) return PAINT_PROPERTY_RATES[landedSubtype] || null;
  if (propertyType === "shoplot") return PAINT_PROPERTY_RATES.shoplot;
  return null; // Condo / Other / Landed with no subtype chosen yet
}

// Returns { amount, onsite, needsScope, fallback }
function calcPaintByProperty(propertyType, landedSubtype, scope, sqft) {
  const rate = getPropertyPaintRate(propertyType, landedSubtype);
  if (rate) {
    if (rate.interior == null || rate.exterior == null) {
      return { amount: 0, onsite: true, needsScope: false, fallback: false };
    }
    if (!scope.interior && !scope.exterior) {
      return { amount: 0, onsite: false, needsScope: true, fallback: false };
    }
    let amount = 0;
    if (scope.interior) amount += rate.interior;
    if (scope.exterior) amount += rate.exterior;
    return { amount, onsite: false, needsScope: false, fallback: false };
  }
  return { amount: calcPaint(sqft), onsite: false, needsScope: false, fallback: true };
}

