function mmToSqft(l, w) {
  const L = parseFloat(l) || 0;
  const W = parseFloat(w) || 0;
  if (!L || !W) return 0;
  return (L * W) / 92903.04; // mm^2 -> sqft
}

function roomsTotalSqft(rooms, roomList) {
  return roomList.reduce((sum, r) => sum + mmToSqft(rooms[r.id]?.l, rooms[r.id]?.w), 0);
}

const PLASTER_RATE = 4.5; // RM per sqft

// ---------------------------------------------------------------------------
// Flooring pricing
// ---------------------------------------------------------------------------
const FLOORING_WASTAGE = 0.1;
const FLOORING_RATES = { "5mm": 5.9, "6.5mm": 6.8 };
const FLOORING_COVERAGE = { "5mm": 24, "6.5mm": 17 };
const FLOORING_SMALL_AREA_THRESHOLD = 200;
const FLOORING_SMALL_AREA_FEE = 500;

function calcFlooringArea(sqft) {
  if (!sqft || sqft <= 0) return 0;
  return sqft * (1 + FLOORING_WASTAGE);
}
function calcFlooringPacks(sqft, thickness) {
  if (!sqft || sqft <= 0) return 0;
  const coverage = FLOORING_COVERAGE[thickness] || 1;
  return Math.ceil(calcFlooringArea(sqft) / coverage);
}
function calcFlooringPurchasedArea(sqft, thickness) {
  const coverage = FLOORING_COVERAGE[thickness] || 1;
  return calcFlooringPacks(sqft, thickness) * coverage;
}
function calcFlooring(sqft, thickness) {
  if (!sqft || sqft <= 0) return 0;
  const rate = FLOORING_RATES[thickness] || 0;
  const base = calcFlooringPurchasedArea(sqft, thickness) * rate;
  const smallAreaFee = sqft < FLOORING_SMALL_AREA_THRESHOLD ? FLOORING_SMALL_AREA_FEE : 0;
  return base + smallAreaFee;
}

