// ---------------------------------------------------------------------------
// Centralised quote computation — used by both the QuotePanel and WhatsApp message
// ---------------------------------------------------------------------------
const QUOTE_PHRASES = {
  zh: { enterArea: "请先输入住家面积", onsite: "现场丈量报价", enterQty: "请输入数量", enterRoom: "请输入房间尺寸", packs: "约", pkg: "包", selectScope: "请选择室内/室外" },
  en: { enterArea: "Enter house area first", onsite: "Quoted on-site", enterQty: "Enter quantity", enterRoom: "Enter room dimensions", packs: "~", pkg: "packs", selectScope: "Select interior/exterior" },
  ms: { enterArea: "Sila masukkan keluasan rumah dahulu", onsite: "Sebut harga di tapak", enterQty: "Masukkan kuantiti", enterRoom: "Masukkan ukuran bilik", packs: "~", pkg: "paket", selectScope: "Pilih dalaman/luaran" },
};

function computeQuote(state) {
  const {
    sqft,
    services,
    paint,
    electricalQty,
    ceilingRooms,
    flooringRooms,
    flooringThickness,
    hacking,
    other,
    lang,
    propertyType,
    landedSubtype,
  } = state;
  const L = SERVICES.reduce((acc, s) => ({ ...acc, [s.id]: s.name[lang] }), {});
  const P = QUOTE_PHRASES[lang];
  const lines = [];
  let total = 0;

  if (services.paint) {
    const colorOnsite = paint.wallMultiColor || paint.ceilingNonWhite;
    const result = calcPaintByProperty(propertyType, landedSubtype, paint.scope, sqft);
    if (result.fallback) {
      // Condo / Other — old sqft-tiered pricing
      if (!sqft) {
        lines.push({ id: "paint", label: L.paint, value: P.enterArea, tbd: true });
      } else if (colorOnsite) {
        lines.push({ id: "paint", label: L.paint, value: P.onsite, tbd: true });
      } else {
        total += result.amount;
        lines.push({ id: "paint", label: L.paint, value: money(result.amount) });
      }
    } else if (result.onsite) {
      lines.push({ id: "paint", label: L.paint, value: P.onsite, tbd: true });
    } else if (result.needsScope) {
      lines.push({ id: "paint", label: L.paint, value: P.selectScope, tbd: true });
    } else if (colorOnsite) {
      lines.push({ id: "paint", label: L.paint, value: P.onsite, tbd: true });
    } else {
      total += result.amount;
      lines.push({ id: "paint", label: L.paint, value: money(result.amount) });
    }
  }

  if (services.wiring) {
    const { total: eTotal, count } = electricalSummary(electricalQty);
    if (count > 0) {
      total += eTotal;
      lines.push({ id: "wiring", label: L.wiring, value: money(eTotal) });
    } else {
      lines.push({ id: "wiring", label: L.wiring, value: P.enterQty, tbd: true });
    }
  }

  if (services.plaster) {
    const sqftC = roomsTotalSqft(ceilingRooms, CEILING_ROOMS);
    if (sqftC > 0) {
      const price = sqftC * PLASTER_RATE;
      total += price;
      lines.push({ id: "plaster", label: L.plaster, value: money(price), sub: `${sqftC.toFixed(0)} sqft` });
    } else {
      lines.push({ id: "plaster", label: L.plaster, value: P.enterRoom, tbd: true });
    }
  }

  if (services.flooring) {
    const sqftF = roomsTotalSqft(flooringRooms, FLOORING_ROOMS);
    if (sqftF > 0) {
      const price = calcFlooring(sqftF, flooringThickness);
      total += price;
      lines.push({
        id: "flooring",
        label: L.flooring,
        value: money(price),
        sub: `${flooringThickness} · ${P.packs}${calcFlooringPacks(sqftF, flooringThickness)}${P.pkg}`,
      });
    } else {
      lines.push({ id: "flooring", label: L.flooring, value: P.enterRoom, tbd: true });
    }
  }

  if (services.hacking) {
    lines.push({
      id: "hacking",
      label: L.hacking,
      value: P.onsite,
      tbd: true,
      sub: hacking.location || hacking.purpose ? `${hacking.location}${hacking.purpose ? " · " + hacking.purpose : ""}` : "",
    });
  }

  if (services.other) {
    lines.push({
      id: "other",
      label: L.other,
      value: P.onsite,
      tbd: true,
      sub: other || "",
    });
  }

  return { lines, total };
}

