// Quote panel — signature element (blueprint spec tag)
// ---------------------------------------------------------------------------
function Corner({ pos }) {
  const base = { position: "absolute", fontSize: 12, color: C.clay, lineHeight: 1 };
  const map = {
    tl: { top: 6, left: 6 },
    tr: { top: 6, right: 6 },
    bl: { bottom: 6, left: 6 },
    br: { bottom: 6, right: 6 },
  };
  return <span style={{ ...base, ...map[pos] }}>+</span>;
}

function Row({ label, value, big, mono }) {
  return (
    <div className="flex items-baseline justify-between gap-3">
      <span style={{ color: C.ink }} className={big ? "text-sm font-medium" : "text-xs"}>
        {label}
      </span>
      <span
        style={{
          fontFamily: mono || big ? "'IBM Plex Mono', monospace" : undefined,
          color: big ? C.clay : C.ink,
        }}
        className={big ? "text-lg font-semibold" : "text-sm"}
      >
        {value}
      </span>
    </div>
  );
}

