const SYSTEM_PROMPT = `你是 BGL Design & Build 的客服助理，负责协助马来西亚的客户了解室内装修风格（Muji 无印风格、优雅风格、现代风格）、物业类型（Condo、Landed[Single/Double Storey、Semi-D、Bungalow]、Shoplot、Other）以及装修服务。
已知报价规则（均以实际输入的面积为准，最终以现场丈量为准）：
- 油漆：价格按物业类型分档，客户可选室内(Interior)/室外(Exterior)，可复选：
  · Landed - Single Storey：室内 RM3500，室外 RM3000
  · Landed - Double Storey：室内 RM6500，室外 RM3500
  · Landed - Semi-D：室内 RM12000，室外 RM8500
  · Landed - Bungalow：室内/室外均需现场丈量报价
  · Shoplot：室内/室外均需现场丈量报价
  · Condo / Other：暂无固定物业类型价目，按住家面积计算：<500平方尺固定 RM1300；500–1200平方尺固定 RM2599；超过1200平方尺按 面积×RM3/平方尺 计算
  墙面最多可选2种颜色，天花板固定白色；若墙面需要3种或以上颜色、或天花板需要非白色，则改为现场丈量报价。
- 油漆用量套餐（仅供参考，与上述价格档次无关，按住家面积计算）：<500sqft: Easy Wash1×15L+Sealer1×15L+天花漆1×18L；500-1200sqft: Easy Wash2×15L+Sealer1×15L+天花漆1×18L；1200-1500sqft: Easy Wash2×15L+1×5L+Sealer1×15L+天花漆1×18L+1×5L；1500-2300sqft: Easy Wash4×15L+Sealer2×15L+天花漆2×18L；2300-2500sqft:5×15L/2×15L/2×18L；2500-3000sqft:6×15L/3×15L/3×18L；3000-3500sqft:7×15L/3×15L/3×18L；3500-4000sqft:8×15L/4×15L/4×18L；超过4000sqft每加500sqft，Easy Wash+1桶，Sealer与天花漆=Easy Wash桶数的一半（取整）。
- 拉电 Electrical Wiring：按项目单价 × 数量计算，包括 Power Track RM100/point、13A Socket Looping RM120/point、13A Socket Point(Direct from DB) RM140/point、T5/LED灯安装 RM10/ft、Lighting Point(Looping) RM80/point、Downlight安装(现有点) RM25/unit、Ceiling Light安装(现有点) RM30/unit、安装吊扇(现有点) RM50/unit、安装带钩吊扇 RM80/unit、New Fan Point(含开关) RM150/point、热水器电点 RM100/point、DB检查/小调整 RM150/job、故障排查 RM150-300/job。
- 天花板 Plaster Ceiling：客户按房间（入门口、客厅、走廊、干湿厨房、yard、主人房、房间1-3、主人房厕所、厕所1-3）输入长×宽(mm)，换算成sqft后 × RM4.5/sqft，各房间加总为总价。
- 地板 Flooring：房间（同上，不含厕所）输入长×宽(mm)换算成sqft加总，再 ×1.1(10%损耗)得铺设面积，除以每包覆盖面积(5mm/包24sqft，6.5mm/包17sqft)进位取整得包数，价格=包数×每包覆盖面积×单价(5mm RM5.9/sqft，6.5mm RM6.8/sqft)。总面积低于200sqft加收RM500小面积附加费。
- Hacking 敲墙拆除、其他 Other：需要现场评估后才能报价，暂无固定价格。
请用简洁、亲切的中文（可视客户输入语言切换英文或马来文）回答，解释风格特色、服务内容与计价方式，并在合适时候建议客户预约免费现场估价。不要编造未提供的具体价格。`;

const CHAT_STRINGS = {
  zh: { greeting: "您好！我是 BGL Design & Build 的客服 👋 有关装修风格、服务项目或报价的问题都可以问我。", placeholder: "输入您的问题…", typing: "正在输入…", close: "关闭聊天窗口" },
  en: { greeting: "Hi! I'm BGL Design & Build's support assistant 👋 Ask me anything about styles, services or pricing.", placeholder: "Type your question…", typing: "Typing…", close: "Close chat" },
  ms: { greeting: "Hai! Saya pembantu khidmat pelanggan BGL Design & Build 👋 Tanya saya tentang gaya, perkhidmatan atau harga.", placeholder: "Taip soalan anda…", typing: "Menaip…", close: "Tutup chat" },
};

function ChatWidget({ open, onClose, label, lang }) {
  const cs = CHAT_STRINGS[lang] || CHAT_STRINGS.zh;
  const [messages, setMessages] = useState([{ role: "assistant", content: cs.greeting }]);
  const [input, setInput] = useState("");
  const [loading, setLoading] = useState(false);
  const scrollRef = useRef(null);

  useEffect(() => {
    if (scrollRef.current) scrollRef.current.scrollTop = scrollRef.current.scrollHeight;
  }, [messages, loading]);

  async function send() {
    const text = input.trim();
    if (!text || loading) return;
    const newMessages = [...messages, { role: "user", content: text }];
    setMessages(newMessages);
    setInput("");
    setLoading(true);
    try {
      const response = await fetch("/api/chat", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          system: SYSTEM_PROMPT,
          messages: newMessages.map((m) => ({ role: m.role, content: m.content })),
        }),
      });
      const data = await response.json();
      const reply = (data.content || []).map((b) => b.text || "").join("\n").trim();
      setMessages((prev) => [...prev, { role: "assistant", content: reply || "抱歉，我暂时无法回复，请稍后再试。" }]);
    } catch (e) {
      setMessages((prev) => [...prev, { role: "assistant", content: "网络似乎出了点问题，请稍后再试一次。" }]);
    } finally {
      setLoading(false);
    }
  }

  if (!open) return null;

  return (
    <div
      className="fixed bottom-24 right-4 w-[92vw] max-w-sm h-[70vh] max-h-[520px] flex flex-col rounded-md shadow-2xl z-50"
      style={{ background: C.white, border: `1px solid ${C.line}` }}
    >
      <div className="flex items-center justify-between px-4 py-3 rounded-t-md" style={{ background: C.blueprint }}>
        <span className="text-sm text-white" style={{ fontFamily: "'IBM Plex Mono', monospace" }}>
          {label}
        </span>
        <button onClick={onClose} aria-label={cs.close}>
          <X size={18} color="white" />
        </button>
      </div>
      <div ref={scrollRef} className="flex-1 overflow-y-auto px-4 py-3 space-y-3">
        {messages.map((m, i) => (
          <div
            key={i}
            className={`text-sm max-w-[85%] px-3 py-2 rounded-md ${m.role === "user" ? "ml-auto text-white" : ""}`}
            style={{
              background: m.role === "user" ? C.clay : C.paper,
              color: m.role === "user" ? "white" : C.ink,
              fontFamily: "'IBM Plex Sans', sans-serif",
              whiteSpace: "pre-wrap",
            }}
          >
            {m.content}
          </div>
        ))}
        {loading && (
          <div className="flex items-center gap-2 text-xs" style={{ color: C.concrete }}>
            <Loader2 size={14} className="animate-spin" /> {cs.typing}
          </div>
        )}
      </div>
      <div className="flex items-center gap-2 p-3" style={{ borderTop: `1px solid ${C.line}` }}>
        <input
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyDown={(e) => e.key === "Enter" && send()}
          placeholder={cs.placeholder}
          className="flex-1 text-sm px-3 py-2 rounded outline-none"
          style={{ border: `1px solid ${C.line}`, fontFamily: "'IBM Plex Sans', sans-serif" }}
        />
        <button onClick={send} disabled={loading} className="p-2 rounded" style={{ background: C.clay }} aria-label="发送">
          <Send size={16} color={C.paper} />
        </button>
      </div>
    </div>
  );
}

