function NumField({ value, onChange, placeholder, className }) {
  return (
    <input
      type="number"
      min="0"
      value={value}
      onChange={(e) => onChange(e.target.value)}
      placeholder={placeholder}
      className={"px-2 py-1.5 text-xs rounded outline-none " + (className || "")}
      style={{ border: `1px solid ${C.line}`, background: C.white, width: 80 }}
    />
  );
}

